class Solution {
public:
    int kthLargestValue(vector<vector<int>>& matrix, int k) {
        int m = matrix.size(), n = matrix[0].size();
        vector<int> vals;
        vals.reserve((size_t)m * n);
        vector<int> col(n, 0);
        for (int i = 0; i < m; i++) {
            int row = 0;
            for (int j = 0; j < n; j++) {
                col[j] ^= matrix[i][j];
                row ^= col[j];
                vals.push_back(row);
            }
        }
        sort(vals.begin(), vals.end(), greater<int>());
        return vals[k - 1];
    }
};

