import heapq

class Solution:
    def kthLargestValue(self, matrix: List[List[int]], k: int) -> int:
        m, n = len(matrix), len(matrix[0])
        heap = []
        col = [0] * n
        for i in range(m):
            row = 0
            for j in range(n):
                col[j] ^= matrix[i][j]
                row ^= col[j]
                if len(heap) < k:
                    heapq.heappush(heap, row)
                elif row > heap[0]:
                    heapq.heapreplace(heap, row)
        return heap[0]

