class Solution {
public:
    int kthLargestValue(vector<vector<int>>& matrix, int k) {
        int m = matrix.size(), n = matrix[0].size();
        priority_queue<int, vector<int>, greater<int>> pq;
        vector<int> col(n, 0);
        for (int i = 0; i < m; i++) {
            int row = 0;
            for (int j = 0; j < n; j++) {
                col[j] ^= matrix[i][j];
                row ^= col[j];
                if ((int)pq.size() < k) pq.push(row);
                else if (row > pq.top()) { pq.pop(); pq.push(row); }
            }
        }
        return pq.top();
    }
};

