var kthLargestValue = function(matrix, k) {
    const m = matrix.length, n = matrix[0].length;
    const col = new Array(n).fill(0);
    const heap = [];
    const push = (v) => {
        heap.push(v);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const popMin = () => {
        const top = heap[0], last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let s = i;
                if (l < heap.length && heap[l] < heap[s]) s = l;
                if (r < heap.length && heap[r] < heap[s]) s = r;
                if (s === i) break;
                [heap[s], heap[i]] = [heap[i], heap[s]];
                i = s;
            }
        }
        return top;
    };
    for (let i = 0; i < m; i++) {
        let row = 0;
        for (let j = 0; j < n; j++) {
            col[j] ^= matrix[i][j];
            row ^= col[j];
            if (heap.length < k) push(row);
            else if (row > heap[0]) { popMin(); push(row); }
        }
    }
    return heap[0];
};
